import React, { useState } from 'react';
import { Heart } from 'lucide-react';
import './Shop.css';
import S1 from '../../Assets/S1.png';
import R1 from '../../Assets/R1.png';
import R2 from '../../Assets/R2.png';


// Product Card Component
const ProductCard = ({ product }) => {
  const [isFavorite, setIsFavorite] = useState(false);

  const handleFavoriteClick = (e) => {
    e.stopPropagation();
    setIsFavorite(!isFavorite);
  };

  const handleCardClick = () => {
    console.log('Product clicked:', product.name);
  };

  return (
    <div className="product-card-shop" onClick={handleCardClick}>
      <div className="product-image-container">
        <img
          src={product.image}
          alt={product.name}
          className="product-image"
        />
        <button className="favorite-btn" onClick={handleFavoriteClick}>
          <Heart
            size={16}
            fill={isFavorite ? '#ff4757' : 'none'}
            color={isFavorite ? '#ff4757' : '#666'}
          />
        </button>
      </div>

      <div className="product-info">
        <h3 className="product-name">{product.name}</h3>
        <p className="product-price">Rs. {product.price.toFixed(2)}</p>
        <div className="product-rating">
          <div className="stars">
            {[...Array(5)].map((_, i) => (
              <span key={i} className={i < product.rating ? 'star filled' : 'star'}>★</span>
            ))}
          </div>
          <span className="review-count">({product.reviews})</span>
        </div>
      </div>
    </div>
  );
};

// Shop Page Component
const ShopPage = () => {
  const [priceRange, setPriceRange] = useState(8000);
  const [selectedFilters, setSelectedFilters] = useState({
    category: [],
    color: [],
  });
  const [sortBy, setSortBy] = useState('default');

  const products = [
    {
      id: 1,
      name: 'Black Tops',
      price: 2500.00,
      rating: 4,
      reviews: 124,
      image: S1,
    },
    {
      id: 2,
      name: 'Winter Jacket',
      price: 5500.00,
      rating: 5,
      reviews: 89,
      image: R1,
    },
    {
      id: 3,
      name: 'Blue Coat',
      price: 8000.00,
      rating: 4,
      reviews: 156,
      image: R2,
    },
    {
      id: 3,
      name: 'Blue Coat',
      price: 8000.00,
      rating: 4,
      reviews: 156,
      image: R3,
    },
    {
      id: 3,
      name: 'Blue Coat',
      price: 8000.00,
      rating: 4,
      reviews: 156,
      image: R4,
    },
    // Add more as needed...
  ];

  const colors = ['#22c55e', '#3b82f6', '#fbbf24', '#f97316', '#ef4444', '#8b5cf6', '#ec4899', '#000000'];

  const handleFilterChange = (type, value) => {
    setSelectedFilters(prev => ({
      ...prev,
      [type]: prev[type].includes(value)
        ? prev[type].filter(item => item !== value)
        : [...prev[type], value]
    }));
  };

  return (
    <div className="shop-container">
      {/* Sidebar */}
      <div className="sidebar">
        <h2>FILTERS</h2>

        {/* Price Range */}
        <div className="filter-section">
          <div className="filter-title">PRICE Rs.</div>
          <div className="price-range">
            <div className="price-display">
              <span>Rs. 500</span>
              <span>Rs. {priceRange}</span>
            </div>
            <input
              type="range"
              min="500"
              max="8000"
              value={priceRange}
              onChange={(e) => setPriceRange(Number(e.target.value))}
              className="range-slider"
            />
          </div>
        </div>

        {/* Category Filter */}
        <div className="filter-section">
          <div className="filter-title">FILTERS</div>
          <div className="filter-group">
            {['Women', 'Ladies', 'Men', 'Small', 'Medium', 'Large'].map(item => (
              <div key={item} className="checkbox-item">
                <input
                  type="checkbox"
                  id={item}
                  onChange={() => handleFilterChange('category', item)}
                />
                <label htmlFor={item}>{item}</label>
              </div>
            ))}
          </div>
        </div>

        {/* Colors */}
        <div className="filter-section">
          <div className="filter-title">Colors</div>
          <div className="color-filters">
            {colors.map((color, index) => (
              <div
                key={index}
                className="color-circle"
                style={{ backgroundColor: color }}
                onClick={() => handleFilterChange('color', color)}
              />
            ))}
          </div>
        </div>

        <button className="apply-btn">Apply Filter</button>
      </div>

      {/* Main Content */}
      <div className="main-content">
        <div className="content-header">
          <div className="breadcrumb">
            Showing (1-12) of 120 Products - Sort by
          </div>
          <div className="sort-dropdown">
            <select
              className="sort-select"
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value)}
            >
              <option value="default">Most Popular</option>
              <option value="price-low">Price: Low to High</option>
              <option value="price-high">Price: High to Low</option>
              <option value="rating">Rating</option>
            </select>
          </div>
        </div>

        <div className="products-grid">
          {products.map(product => (
            <ProductCard key={product.id} product={product} />
          ))}
        </div>

        {/* Pagination */}
        <div className="pagination">
          <button className="page-btn">←</button>
          {[1, 2, 3, 4, 5, 6].map(n => (
